<?php

declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';

use EventMenu\Core\Database;
use EventMenu\Core\Security;
use EventMenu\Services\CheckoutService;
use EventMenu\Services\OrderFulfillmentService;

$pdo=Database::connection();$token=trim((string)($_GET['t']??''));$error=null;
function p_money(int$c):string{return 'R$ '.number_format($c/100,2,',','.');}
function p_qty(float|int|string$v):string{$q=(float)$v;return abs($q-round($q))<0.0005?(string)(int)round($q):rtrim(rtrim(number_format($q,3,',','.'),'0'),',');}
function p_channel(string$c):string{return match($c){'pickup'=>'Retirada no local','counter'=>'Balcão / PDV','delivery'=>'Delivery','table'=>'Mesa / comanda','event'=>'Evento / Ingresso','event_bar'=>'Evento / Bar',default=>$c};}
function allowed_checkout_url(string$provider,string$url):bool{$p=parse_url($url);if(($p['scheme']??'')!=='https'||empty($p['host']))return false;$h=strtolower($p['host']);$allowed=['stripe'=>['stripe.com'],'mercadopago'=>['mercadopago.com','mercadopago.com.br'],'pagbank'=>['pagseguro.uol.com.br','pagbank.com.br']];foreach($allowed[$provider]??[]as$suffix){if($h===$suffix||str_ends_with($h,'.'.$suffix))return true;}return false;}

if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!Security::validateCsrf($_POST['_csrf']??null))$error='Sessão expirada.';
    else{try{$provider=(string)($_POST['provider']??'');$checkout=(new CheckoutService())->create($token,$provider);if(!allowed_checkout_url($checkout['provider'],$checkout['url']))throw new RuntimeException('URL de checkout rejeitada por segurança.');header('Location: '.$checkout['url'],true,303);exit;}catch(Throwable$e){$error=$e->getMessage();}}
}
$s=$pdo->prepare('SELECT o.*,t.name tenant_name,t.slug tenant_slug,c.name customer_name FROM orders o JOIN tenants t ON t.id=o.tenant_id LEFT JOIN customers c ON c.id=o.customer_id WHERE o.public_token=? AND t.status="active" LIMIT 1');$s->execute([$token]);$order=$s->fetch();if(!$order){http_response_code(404);exit('Pedido não encontrado.');}
$items=$pdo->prepare('SELECT * FROM order_items WHERE order_id=? ORDER BY id');$items->execute([$order['id']]);$items=$items->fetchAll();
$g=$pdo->prepare('SELECT provider FROM payment_gateways WHERE tenant_id=? AND active=1 AND provider IN ("stripe","pagbank","mercadopago") ORDER BY provider');$g->execute([$order['tenant_id']]);$gateways=$g->fetchAll(PDO::FETCH_COLUMN);
$tickets=$pdo->prepare('SELECT t.*,e.name event_name,e.starts_at event_starts_at,e.venue event_venue,e.address event_address,b.name batch_name,tt.name ticket_type_name FROM tickets t JOIN events e ON e.id=t.event_id JOIN ticket_batches b ON b.id=t.batch_id LEFT JOIN ticket_types tt ON tt.id=b.ticket_type_id WHERE t.order_id=? ORDER BY t.id');$tickets->execute([$order['id']]);$tickets=$tickets->fetchAll();
$eventInfo=$tickets?$tickets[0]:null;
$fulfillment=new OrderFulfillmentService();$hasOrderQr=$fulfillment->supportsChannel((string)$order['channel'])&&!empty($order['public_token']);$qrDataUri=$hasOrderQr?$fulfillment->qrDataUri((string)$order['public_token'],300):null;try{$progress=$hasOrderQr?$fulfillment->publicProgress((int)$order['tenant_id'],(int)$order['id']):null;}catch(Throwable){$progress=null;}
$paid=(string)$order['payment_status']==='paid';$cancelled=(string)$order['status']==='cancelled';
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#6236df"><meta http-equiv="Cache-Control" content="no-store"><title>Pedido #<?= (int)$order['id'] ?> — EventMenu</title><style>
:root{--primary:#6236df;--primary-dark:#4320aa;--bg:#f7f7fb;--surface:#fff;--text:#252137;--muted:#77748a;--line:#e7e4ef;--soft:#f1edff;--ok:#2ea969;--warn:#b56a12;--danger:#b23d4a;--shadow:0 14px 40px rgba(44,34,79,.08)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}button,input{font:inherit}.shell{width:min(820px,100%);margin:auto;padding:18px 16px 70px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.brand{font-size:20px;font-weight:950;color:#20134f}.brand span{color:var(--primary)}.org{font-size:12px;color:var(--muted)}.card{background:#fff;border:1px solid var(--line);border-radius:20px;padding:22px;box-shadow:var(--shadow)}.status-row{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}.channel{display:inline-flex;padding:7px 10px;background:var(--soft);border-radius:999px;color:var(--primary-dark);font-size:11px;font-weight:850}.payment{display:inline-flex;padding:7px 10px;border-radius:999px;background:#f4f3f7;color:#5f5a6b;font-size:11px;font-weight:850}.payment.paid{background:#eaf8f0;color:#21794d}.title h1{font-size:34px;letter-spacing:-1px;margin:10px 0 3px}.title p{margin:0;color:var(--muted)}.event-box{margin:18px 0;padding:16px;border-radius:16px;background:linear-gradient(135deg,#20134f,#6236df);color:#fff}.event-box small{opacity:.75}.event-box h2{margin:5px 0 7px;font-size:22px}.event-meta{display:flex;flex-wrap:wrap;gap:8px;font-size:12px;opacity:.9}.items{margin:18px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.item{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:15px;padding:13px 0;border-bottom:1px solid var(--line)}.item:last-child{border-bottom:0}.item strong{display:block}.item small{color:var(--muted)}.totals{display:grid;gap:8px;margin:14px 0}.total-row{display:flex;justify-content:space-between;gap:12px}.total-row.grand{font-size:21px;font-weight:950;padding-top:10px;border-top:1px solid var(--line)}.alert{padding:13px 14px;border-radius:13px;margin:15px 0;background:#fff4e5;border:1px solid #f0d5a7;color:#7c5518}.alert.ok{background:#eaf8f0;border-color:#c9ebd8;color:#216d49}.alert.error{background:#fff0f1;border-color:#efc9ce;color:#9a3844}.section-title{margin:24px 0 10px}.section-title h2{margin:0;font-size:21px}.pay-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}.pay-grid button,.button{width:100%;border:0;border-radius:12px;padding:13px 15px;font-weight:900;cursor:pointer}.primary{background:var(--primary);color:#fff}.secondary{background:#fff;color:var(--primary);border:1px solid var(--line)}.qr-card{display:grid;grid-template-columns:210px minmax(0,1fr);gap:20px;align-items:center;margin-top:20px;padding:18px;border-radius:18px;background:#fbfaff;border:1px solid #ded7f5}.qr-box{background:#fff;border:1px solid var(--line);border-radius:14px;padding:10px}.qr-box img{display:block;width:100%;height:auto}.qr-card h2{margin:4px 0 8px}.progress{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:12px}.progress div{background:#fff;border:1px solid var(--line);border-radius:12px;padding:10px}.progress small,.progress strong{display:block}.progress small{font-size:10px;color:var(--muted)}.progress strong{font-size:20px}.ticket-list{display:grid;gap:9px;margin-top:10px}.ticket-link{display:flex;justify-content:space-between;gap:12px;align-items:center;border:1px solid var(--line);border-radius:13px;padding:12px 14px;color:var(--text);text-decoration:none}.ticket-link strong{color:var(--primary)}.foot{text-align:center;color:#9893a4;font-size:11px;padding:24px 0}
@media(max-width:620px){.shell{padding:12px 10px 50px}.top{align-items:flex-start}.org{display:none}.card{padding:17px;border-radius:16px}.title h1{font-size:29px}.status-row{flex-direction:column}.qr-card{grid-template-columns:1fr}.qr-box{max-width:245px;margin:auto}.progress{grid-template-columns:repeat(3,1fr)}.event-meta{display:grid;gap:5px}.ticket-link{align-items:flex-start;flex-direction:column}}
</style></head><body><main class="shell"><header class="top"><div class="brand">EventMenu <span>Premium</span></div><div class="org"><?= Security::e($order['tenant_name']) ?></div></header><section class="card"><div class="status-row"><div class="title"><span class="channel"><?= Security::e(p_channel((string)$order['channel'])) ?></span><h1>Pedido #<?= (int)$order['id'] ?></h1><p><?= Security::e($order['customer_name']??'Cliente') ?> · <?= Security::e(date('d/m/Y H:i',strtotime((string)$order['created_at']))) ?></p></div><span class="payment<?= $paid?' paid':'' ?>"><?= $paid?'Pagamento confirmado':Security::e((string)$order['payment_status']) ?></span></div>
<?php if($eventInfo):?><div class="event-box"><small>SEU EVENTO</small><h2><?= Security::e($eventInfo['event_name']) ?></h2><div class="event-meta"><span><?= Security::e(date('d/m/Y · H:i',strtotime((string)$eventInfo['event_starts_at']))) ?></span><?php if($eventInfo['event_venue']):?><span>• <?= Security::e($eventInfo['event_venue']) ?></span><?php endif;?><?php if($eventInfo['ticket_type_name']):?><span>• <?= Security::e($eventInfo['ticket_type_name']) ?></span><?php endif;?></div></div><?php endif;?>
<?php if($error):?><div class="alert error"><?= Security::e($error) ?></div><?php endif;?>
<div class="items"><?php foreach($items as$i):?><div class="item"><div><strong><?= Security::e($i['name_snapshot']) ?></strong><small><?= p_qty($i['quantity']) ?> × <?= p_money((int)$i['unit_price_cents']) ?></small></div><strong><?= p_money((int)$i['total_cents']) ?></strong></div><?php endforeach;?></div><div class="totals"><?php if((int)$order['discount_cents']>0):?><div class="total-row"><span>Desconto</span><strong>- <?= p_money((int)$order['discount_cents']) ?></strong></div><?php endif;?><?php if((int)($order['delivery_fee_cents']??0)>0):?><div class="total-row"><span>Taxa de entrega</span><strong><?= p_money((int)$order['delivery_fee_cents']) ?></strong></div><?php endif;?><div class="total-row grand"><span>Total</span><span><?= p_money((int)$order['total_cents']) ?></span></div></div>
<?php if($cancelled):?><div class="alert error">Este pedido foi cancelado.</div><?php elseif($paid):?><div class="alert ok">Pagamento confirmado pelo servidor. Seu pedido está válido.</div><?php elseif((int)$order['total_cents']>0):?><div class="section-title"><h2>Escolha como pagar</h2></div><?php if($gateways):?><div class="pay-grid"><?php foreach($gateways as$provider):?><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="provider" value="<?= Security::e($provider) ?>"><button class="primary">Pagar com <?= Security::e(['stripe'=>'Stripe','mercadopago'=>'Mercado Pago','pagbank'=>'PagBank'][$provider]??$provider) ?></button></form><?php endforeach;?></div><p style="color:var(--muted);font-size:12px">A confirmação ocorre somente após validação segura do pagamento.</p><?php else:?><div class="alert">Nenhum pagamento online foi habilitado por esta empresa. Entre em contato com a organização para concluir o pagamento.</div><?php endif;?><?php endif;?>
<?php if($hasOrderQr):?><section class="qr-card"><div class="qr-box"><img src="<?= Security::e((string)$qrDataUri) ?>" alt="QR do pedido"></div><div><small style="font-weight:900;color:var(--primary)">QR DO PEDIDO</small><h2><?= $order['channel']==='pickup'?'Apresente na retirada':'Identificação do pedido' ?></h2><p style="color:var(--muted)"><?= $order['channel']==='pickup'?'Mostre este QR ao responsável pela retirada. Retiradas parciais continuam usando o mesmo código.':'Este QR identifica o pedido para conferência da equipe.' ?></p><?php if($progress):?><div class="progress"><div><small>Pedido</small><strong><?= p_qty($progress['ordered_quantity']) ?></strong></div><div><small>Entregue</small><strong><?= p_qty($progress['fulfilled_quantity']) ?></strong></div><div><small>Falta</small><strong><?= p_qty($progress['remaining_quantity']) ?></strong></div></div><?php endif;?></div></section><?php elseif($order['channel']==='table'):?><div class="alert ok">Pedido vinculado à mesa/comanda. Não é necessário QR de retirada.</div><?php endif;?>
<?php if($paid&&$tickets):?><div class="section-title"><h2>Seus ingressos</h2></div><div class="ticket-list"><?php foreach($tickets as$t):$ticketUrl=app_url('ingresso.php?t='.rawurlencode((string)$t['qr_token']));?><a class="ticket-link" href="<?= Security::e($ticketUrl) ?>"><div><strong><?= Security::e($t['ticket_type_name']?:'Ingresso') ?></strong><br><small><?= Security::e($t['batch_name']) ?> · <?= Security::e($t['code']) ?></small></div><span>Abrir QR →</span></a><?php endforeach;?></div><?php endif;?></section><div class="foot">EventMenu — gastronomia, eventos e boas experiências.</div></main><?php if(!$cancelled&&!$paid):?><script>setTimeout(()=>location.reload(),20000);</script><?php endif;?></body></html>